import express from "express";
import { middlewareLogResponse } from "./api/middleware/middlewareLogRes.js";
import { asyncError, errorHandler, middlewareMetricsInc } from "./api/middleware.js";
import { handlerReset } from "./admin/reset.js";
import { handlerMetrics } from "./admin/metrics.js";
import postgres from "postgres";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import { drizzle } from "drizzle-orm/postgres-js";
import { config } from "./config.js";
import { handlerUsersCreate } from "./api/users.js";
import { handlerChirp, handlerChirpsRetrieve, handlerSingleChirp } from "./api/chirps.js";
import { handlerLogin } from "./api/login.js";
const migrationClient = postgres(config.db.dbURL, { max: 1 });
await migrate(drizzle(migrationClient), config.db.migrationConfig);
const app = express();
app.use(express.json());
app.use(middlewareLogResponse);
app.use("/app", middlewareMetricsInc, express.static("./src/app"));
app.get("/admin/metrics", handlerMetrics);
app.get("/api/chirps", asyncError(handlerChirpsRetrieve));
app.get("/api/chirps/:chirpID", asyncError(handlerSingleChirp));
app.post("/api/login", asyncError(handlerLogin));
app.post("/admin/reset", asyncError(handlerReset));
app.post("/api/users", asyncError(handlerUsersCreate));
app.post("/api/chirps", asyncError(handlerChirp));
app.listen(config.api.port, () => {
    console.log(`Server is running at http://localhost:${config.api.port}`);
});
app.use(errorHandler);
